// Process YouTube Analytics data
const analyticsData = $input.first().json;
const targetRevenue = 75000;

// Initialize totals
let totalRevenue = 0;
let totalViews = 0;
let totalSubscribers = 0;
let totalWatchTime = 0;

// Process rows if they exist
if (analyticsData.rows && analyticsData.rows.length > 0) {
  analyticsData.rows.forEach(row => {
    totalRevenue += parseFloat(row[1] || 0);
    totalViews += parseInt(row[2] || 0);
    totalSubscribers += parseInt(row[3] || 0);
    totalWatchTime += parseFloat(row[4] || 0);
  });
}

// Calculate progress
const progressPercentage = (totalRevenue / targetRevenue) * 100;
const remainingRevenue = targetRevenue - totalRevenue;
const daysInMonth = new Date(new Date().getFullYear(), new Date().getMonth() + 1, 0).getDate();
const currentDay = new Date().getDate();
const daysRemaining = daysInMonth - currentDay;
const dailyTargetRemaining = daysRemaining > 0 ? remainingRevenue / daysRemaining : 0;

// Calculate RPM (Revenue per Mille)
const rpm = totalViews > 0 ? (totalRevenue / totalViews) * 1000 : 0;

// Determine status
let status = 'on_track';
let statusEmoji = '📈';
let statusMessage = 'On track to meet revenue target';

if (progressPercentage >= 100) {
  status = 'target_achieved';
  statusEmoji = '🎉';
  statusMessage = 'Revenue target achieved!';
} else if (progressPercentage < 50 && currentDay > 15) {
  status = 'behind_target';
  statusEmoji = '⚠️';
  statusMessage = 'Behind revenue target';
} else if (progressPercentage < 25 && currentDay > 20) {
  status = 'critical';
  statusEmoji = '🚨';
  statusMessage = 'Critically behind revenue target';
}

// Format currency
const formatCurrency = (amount) => {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD'
  }).format(amount);
};

// Format numbers
const formatNumber = (num) => {
  return new Intl.NumberFormat('en-US').format(num);
};

return {
  json: {
    // Revenue metrics
    total_revenue: totalRevenue,
    target_revenue: targetRevenue,
    remaining_revenue: remainingRevenue,
    progress_percentage: Math.round(progressPercentage * 100) / 100,

    // Performance metrics
    total_views: totalViews,
    total_subscribers: totalSubscribers,
    total_watch_time: totalWatchTime,
    rpm: Math.round(rpm * 100) / 100,

    // Time metrics
    current_day: currentDay,
    days_remaining: daysRemaining,
    daily_target_remaining: Math.round(dailyTargetRemaining * 100) / 100,

    // Status
    status: status,
    status_emoji: statusEmoji,
    status_message: statusMessage,

    // Formatted values for display
    formatted: {
      total_revenue: formatCurrency(totalRevenue),
      target_revenue: formatCurrency(targetRevenue),
      remaining_revenue: formatCurrency(remainingRevenue),
      daily_target_remaining: formatCurrency(dailyTargetRemaining),
      total_views: formatNumber(totalViews),
      total_subscribers: formatNumber(totalSubscribers),
      rpm: formatCurrency(rpm)
    },

    // Timestamp
    calculated_at: new Date().toISOString(),
    month: new Date().getMonth() + 1,
    year: new Date().getFullYear()
  }
};

